<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { FontAwesomeIcon } from '@fortawesome/vue-fontawesome'
import { faMagnifyingGlass, faSliders, faUser, faList, faMessage, faClockRotateLeft, faBookmark } from '@fortawesome/free-solid-svg-icons'
import { getProfileAvatar } from '../services/profileAvatar'

const router = useRouter()
const avatarUrl = getProfileAvatar()
const signedInUser = JSON.parse(localStorage.getItem('taste-user') ?? '{}') as { id?: string }
const defaultListings = [
  { id: 'mango', name: 'Mango', image: '/images/mango.jpg' },
  { id: 'avocado', name: 'Avocado', image: '/images/avocado.jpg' },
]
const storedListings = JSON.parse(localStorage.getItem('taste-farmer-listings') ?? 'null') as typeof defaultListings | null
const listings = ref(storedListings?.map((listing) => ({
  ...listing,
  image: listing.id === 'mango' ? '/images/mango.jpg' : listing.id === 'avocado' ? '/images/avocado.jpg' : listing.image,
})) ?? defaultListings)
type RequestState = 'Pending' | 'Accepted' | 'Rejected' | 'Completed'
type StoredBuyRequest = { id: string; buyer?: string; farmerId?: string; crop?: string; weight?: string; discount?: string; location?: string; note?: string; status?: RequestState }
const storedRequests = JSON.parse(localStorage.getItem('taste-buy-requests') ?? '[]') as StoredBuyRequest[]
const requests = ref(storedRequests.filter((request) => request.farmerId === (signedInUser.id ?? 'fmr-001')).map((request) => ({ ...request, buyer: request.buyer ?? 'Customer', crop: request.crop ?? '', weight: request.weight ?? '', discount: request.discount ?? '', location: request.location ?? 'Phnom Penh, Cambodia', note: request.note ?? '', state: request.status ?? 'Pending' })))
const pendingCount = computed(() => requests.value.filter((request) => request.state === 'Pending').length)
const rejectedCount = computed(() => requests.value.filter((request) => request.state === 'Rejected').length)
const completedCount = computed(() => requests.value.filter((request) => request.state === 'Completed').length)
function updateRequest(id: string | number, state: 'Accepted' | 'Rejected' | 'Completed') {
  const request = requests.value.find((item) => item.id === id)
  if (request) {
    request.state = state
    const allRequests = JSON.parse(localStorage.getItem('taste-buy-requests') ?? '[]') as StoredBuyRequest[]
    localStorage.setItem('taste-buy-requests', JSON.stringify(allRequests.map((item) => item.id === id ? { ...item, status: state } : item)))
  }
}
</script>

<template>
  <main class="farmer-portal-page">
    <header class="portal-header"><button class="portal-logo" @click="router.push('/browse')">Taste</button><label class="portal-search"><FontAwesomeIcon :icon="faMagnifyingGlass" /><input placeholder="Search for your products" /></label><button class="portal-header-link" @click="router.push('/farmer-portal')">Farmer Portal</button><button class="portal-header-icon" aria-label="Filters" @click="router.push('/browse')"><FontAwesomeIcon :icon="faSliders" /></button><button class="portal-profile" aria-label="User account" @click="router.push('/account')"><img v-if="avatarUrl" :src="avatarUrl" alt="Profile picture" /><FontAwesomeIcon v-else :icon="faUser" /></button></header>
    <div class="portal-layout"><aside class="portal-sidebar" aria-label="Browse navigation"><button aria-label="Listings" @click="router.push('/browse')"><FontAwesomeIcon :icon="faList" /></button><button aria-label="Messages" @click="router.push('/messages')"><FontAwesomeIcon :icon="faMessage" /></button><button aria-label="History" @click="router.push('/history')"><FontAwesomeIcon :icon="faClockRotateLeft" /></button><button aria-label="Saved listings" @click="router.push('/saved')"><FontAwesomeIcon :icon="faBookmark" /></button></aside>
      <section class="portal-content"><div class="portal-title"><h1>My Active Listings</h1><button @click="router.push('/submit')">+ Add New Listing</button></div>
        <div class="portal-stats"><article class="active-stat"><h2>Active Listings</h2><strong>{{ listings.length }}</strong></article><article class="pending-stat"><h2>Pending Requests</h2><strong>{{ pendingCount }}</strong></article><article class="rejected-stat"><h2>Rejected Orders</h2><strong>{{ rejectedCount }}</strong></article><article class="completed-stat"><h2>Completed Orders</h2><strong>{{ completedCount }}</strong></article></div>
        <div class="portal-listings"><article v-for="listing in listings" :key="listing.id" class="portal-listing"><img :src="listing.image" :alt="listing.name" /><div class="portal-listing-title"><span>{{ listing.name }}</span><span>${{ Number(listing.price ?? 3).toFixed(2) }}/KG</span></div><div class="portal-listing-meta"><span>Location : {{ listing.location ?? 'Phnom Penh · Cambodia' }}</span><span>Available : {{ listing.quantity ?? 20 }} KG</span></div><div class="portal-listing-meta"><span>John (Farmer) | ID : 22ddd1kd</span><span>Status : {{ listing.status === 'Pre-Order' ? 'Pre-Order' : 'In Stock' }}</span></div><div class="portal-listing-actions"><FontAwesomeIcon :icon="faBookmark" /><button @click="router.push('/crops/' + listing.id)">View and Offer</button></div></article></div>
        <section class="buy-requests"><h2>Buy Requests</h2><article v-for="request in requests" :key="request.id" class="buy-request"><div class="buyer"><FontAwesomeIcon :icon="faUser" /><span><strong>{{ request.buyer }}</strong><small>{{ request.location }}</small></span></div><div class="request-details"><span><strong>Crop Type</strong>{{ request.crop }}</span><span><strong>Weight</strong>{{ request.weight }}</span><span><strong>Requesting discount</strong>{{ request.discount }}</span><span><strong>Location</strong>{{ request.location }}</span></div><p class="request-note"><strong>Notes :</strong> “{{ request.note }}”</p><div class="request-actions" v-if="request.state === 'Pending'"><button class="reject" @click="updateRequest(request.id, 'Rejected')">Reject</button><button class="accept" @click="updateRequest(request.id, 'Accepted')">Accept</button></div><label v-if="request.state === 'Pending' || request.state === 'Accepted'" class="complete-request"><input type="checkbox" @change="updateRequest(request.id, 'Completed')" /> Mark as Completed</label><strong v-else class="request-result">{{ request.state }}</strong></article></section>
      </section>
    </div>
  </main>
</template>

