.portal-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:clamp(14px,4.5vw,66px);max-width:1157px}.portal-stats article{min-width:0;padding:14px 16px}.portal-stats .pending-stat{background:#cbbfc5}.portal-stats .rejected-stat{background:#df7777}.portal-stats .completed-stat{background:#82958b}.portal-stats h2{font-size:clamp(11px,1.1vw,16px);white-space:nowrap}.portal-stats .pending-stat h2{color:#66535f}.portal-stats .rejected-stat h2{color:#111}.portal-stats .completed-stat h2{color:#28764e}.complete-request{position:absolute;right:110px;bottom:16px;display:flex;align-items:center;gap:10px;font:bold 16px 'DM Mono',monospace}.complete-request input{width:24px;height:24px;accent-color:#5da47f}@media(max-width:1000px){.portal-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}@media(max-width:650px){.portal-stats{grid-template-columns:1fr}.complete-request{position:static;margin-top:14px;justify-content:flex-end}}
